const ConsumableInfo* ScriptSession::consumableInfo(std::uint32_t ability){
    if(auto found=consumableInfo_.find(ability);found!=consumableInfo_.end())return found->second?&*found->second:nullptr;auto& data=definitions();auto code=data.field(ability,"AbilityData","code",ObjectData::name(ability));std::optional<ConsumableInfo> value;
    if(code=="AIrg" || code=="AIvu" || code=="AIsp" || code=="AIsa" || code=="AIha" || code=="AImr" || code=="AIra" || code=="AIdi" || code=="AIda" || code=="ANse"){
        value.emplace();auto& c=*value;auto& s=c.spell;s.ability=ability;s.level=1;s.kind=code=="AIdi"?SpellKind::Dispel:SpellKind::Channel;s.channelOptions=12;auto field=[&](const char* key){return data.number(ability,"AbilityData",std::string(key)+"1");};auto count=[&](const char* key,unsigned maximum){auto n=field(key);if(n<0 || n>maximum || n!=std::floor(n))throw std::runtime_error("Invalid consumable flag: "+ObjectData::name(ability));return unsigned(n);};s.mana=field("Cost");s.cooldown=field("Cool");s.range=field("Rng");s.area=field("Area");s.duration=field("Dur");s.heroDuration=field("HeroDur");s.amount=field("DataA");s.secondary=field("DataB");
        if(code=="AIrg"){c.kind=ConsumableKind::Regeneration;c.heal=s.amount;c.mana=s.secondary;c.fullFlags=count("DataC",3);c.noTarget=count("DataD",1)!=0;c.breakOnDamage=count("DataE",1)!=0;}
        else if(code=="AIvu")c.kind=ConsumableKind::Invulnerability;
        else if(code=="ANse")c.kind=ConsumableKind::SpellShield;
        else if(code=="AIsp" || code=="AIsa"){c.kind=ConsumableKind::Speed;s.moveBonus=s.amount;c.moveLimit=gameplayNumber("MaxUnitSpeed",400);if(c.moveLimit<=0 || c.moveLimit>100000)throw std::runtime_error("Invalid source maximum unit speed");}
        else if(code=="AIdi"){c.kind=ConsumableKind::Dispel;c.noTarget=false;}
        else if(code=="AIda"){c.kind=ConsumableKind::Protection;s.armor=s.amount;c.heal=s.secondary;c.mana=field("DataC");if(!std::isfinite(c.mana) || c.mana<0 || c.mana>1000000)throw std::runtime_error("Protection mana outside supported range");}
        else {c.kind=ConsumableKind::Restoration;c.heal=code=="AImr"?0:s.amount;c.mana=code=="AImr"?s.amount:code=="AIra"?s.secondary:0;}
        for(auto n:{s.mana,s.cooldown,s.range,s.area,s.duration,s.heroDuration,s.secondary})if(!std::isfinite(n) || n<0 || n>1000000)throw std::runtime_error("Consumable parameter outside supported range: "+ObjectData::name(ability));if(!std::isfinite(s.amount) || std::abs(s.amount)>1000000 || (s.amount<0 && c.kind!=ConsumableKind::Protection))throw std::runtime_error("Consumable effect outside supported range: "+ObjectData::name(ability));
        if(c.kind==ConsumableKind::Regeneration && c.heal<=0 && c.mana<=0)throw std::runtime_error("Regeneration consumable requires a resource effect: "+ObjectData::name(ability));
        std::stringstream targets(data.field(ability,"AbilityData","targs1"));std::string part;while(std::getline(targets,part,',')){auto first=part.find_first_not_of(" \t\"");if(first!=std::string::npos){part=part.substr(first,part.find_last_not_of(" \t\"")-first+1);if(part!="_" && part!="-")s.allowed.insert(part);}}
        if(c.kind==ConsumableKind::Regeneration || c.kind==ConsumableKind::Invulnerability || c.kind==ConsumableKind::Speed || c.kind==ConsumableKind::Protection || c.kind==ConsumableKind::SpellShield){std::stringstream input(data.field(ability,"AbilityData","BuffID1"));std::vector<std::uint32_t> buffs;while(std::getline(input,part,',')){if(part.size()!=4)throw std::runtime_error("Invalid consumable source buff");buffs.push_back(ObjectData::code(part));}auto index=c.kind==ConsumableKind::Regeneration?(c.heal>0?(c.mana>0?0u:1u):2u):0u;if(index>=buffs.size() || (c.kind!=ConsumableKind::SpellShield && (s.duration<=0 || s.heroDuration<=0)))throw std::runtime_error("Timed consumable requires source buff and durations");s.buff=buffs[index];}
    }auto found=consumableInfo_.emplace(ability,std::move(value)).first;return found->second?&*found->second:nullptr;
}
bool ScriptSession::useConsumable(std::uint32_t source,std::uint32_t itemId,std::uint32_t target,std::optional<WorldPoint> point,const ConsumableInfo& c){
    auto user=units_.at(source);auto held=items_.at(itemId);auto& s=c.spell;auto& data=definitions();bool powerup=data.number(held->type,"ItemData","powerup")!=0;if(!powerup && !inventoryFlag(*user,"DataC"))return false;bool pointTarget=c.kind==ConsumableKind::Dispel && !powerup,unitTarget=!c.noTarget && !pointTarget && c.kind!=ConsumableKind::Dispel && s.area<=0;if(point.has_value()!=pointTarget || (!unitTarget && target && target!=source))return false;if(unitTarget && !target)return false;
    auto destination=unitTarget?target:source;if(!alive(destination,NativeKind::Unit))return false;auto selected=units_.at(destination);auto where=point.value_or(WorldPoint{selected->x,selected->y});if(!std::isfinite(number(where.x)) || !std::isfinite(number(where.y)))throw std::runtime_error("Invalid consumable target point");where=requireWorld().clamp(where);if((pointTarget || unitTarget) && s.range>0 && std::hypot(number(where.x)-number(user->x),number(where.y)-number(user->y))>s.range+user->collision+(unitTarget?selected->collision:0))return false;
    auto group=data.field(held->type,"ItemData","cooldownID",ObjectData::name(s.ability));if(auto found=user->itemCooldowns.find(group);found!=user->itemCooldowns.end() && found->second>simulationTime_)return false;bool perishable=data.number(held->type,"ItemData","perishable")!=0,limited=held->charges>0 || data.number(held->type,"ItemData","uses")>0;if((limited && held->charges<=0) || number(user->mana)<s.mana)return false;
    std::vector<std::uint32_t> targets;if(s.area>0)targets=spellTargets(source,s,where,user->owner);else if(!unitTarget || spellTarget(*user,*selected,s,true))targets.push_back(destination);auto useful=[&](const UnitState& u){if(c.kind==ConsumableKind::Dispel || c.kind==ConsumableKind::Protection || c.kind==ConsumableKind::SpellShield || (c.kind==ConsumableKind::Restoration && c.heal==0 && c.mana==0))return true;if(c.kind==ConsumableKind::Invulnerability)return !u.building;if(c.kind==ConsumableKind::Speed)return !u.stationaryBuilding() && number(u.currentMoveSpeed())>0;return (c.heal>0 && ((c.fullFlags&1) || number(u.life)<number(u.maxLife))) || (c.mana>0 && ((c.fullFlags&2) || number(u.mana)<number(u.maxMana)));};std::erase_if(targets,[&](auto id){return !useful(*units_.at(id));});if(targets.empty() && !powerup && c.kind!=ConsumableKind::Dispel)return false;
    auto owner=user->owner;auto ownership=user->ownerRevision,death=user->deathRevision,revision=user->castRevision,combat=user->combat.revision;auto current=[&]{return alive(source,NativeKind::Unit) && units_.at(source)==user && !user->removing && !user->paused && number(user->life)>0 && user->owner==owner && user->ownerRevision==ownership && user->deathRevision==death && user->castRevision==revision && user->combat.revision==combat;};auto ready=[&]{if(!current() || !alive(itemId,NativeKind::Item) || items_.at(itemId)!=held || held->holder!=source || (!powerup && !inventoryFlag(*user,"DataC")) || (limited && held->charges<=0) || number(user->mana)<s.mana)return false;auto found=user->itemCooldowns.find(group);return found==user->itemCooldowns.end() || found->second<=simulationTime_;};CastOrder cast;cast.caster=source;cast.item=itemId;cast.owner=owner;cast.spell=s;cast.spell.targeting=pointTarget?SpellTargeting::Point:unitTarget?SpellTargeting::Unit:SpellTargeting::None;cast.target=unitTarget?target:0;cast.point=where;cast.abilityHandle=abilityHandle(source,s.ability);for(unsigned stage=0;stage<2;++stage){spellEvent(source,cast,stage);if(!ready())return true;}
    breakInvisibility(*user);user->mana=real(number(user->mana)-s.mana);if(limited)--held->charges;user->itemCooldowns[group]=simulationTime_+s.cooldown;ScriptContext context;context.manipulatedItem=itemId;unitEvent(source,50,87,context);if(perishable && limited && alive(itemId,NativeKind::Item) && held->charges==0)removeItem(itemId);if(!current())return true;spellEvent(source,cast,2);if(!current())return true;queueSpellSound(s.ability,{user->x,user->y});spellVisual(s,"CasterArt",source,{user->x,user->y});
    for(auto id:targets){if(!alive(source,NativeKind::Unit))break;if(!alive(id,NativeKind::Unit))continue;auto u=units_.at(id);if(u->removing || number(u->life)<=0)continue;if(c.kind==ConsumableKind::Dispel){dispelSpell(source,id,s);continue;}if(c.kind==ConsumableKind::Restoration){if(c.heal>0)unitLife(runtime_.handle("unit",id),real(number(u->life)+spellHealAmount(*u,c.heal)));if(alive(id,NativeKind::Unit) && number(u->life)>0 && c.mana>0)u->mana=real(std::min(number(u->maxMana),number(u->mana)+c.mana));spellVisual(s,"TargetArt",id,{u->x,u->y});continue;}
        if(c.kind==ConsumableKind::Protection){if(c.heal>0)unitLife(runtime_.handle("unit",id),real(number(u->life)+spellHealAmount(*u,c.heal)));if(!alive(id,NativeKind::Unit) || u->removing || number(u->life)<=0)continue;if(c.mana>0)u->mana=real(std::min(number(u->maxMana),number(u->mana)+c.mana));}if(auto old=u->buffs.find(s.buff);old!=u->buffs.end()){releaseBuff(old->second);u->buffs.erase(old);}UnitBuff b;b.id=s.buff;b.source=source;b.target=id;b.remaining=u->hero?s.heroDuration:s.duration;b.positive=true;b.kind=c.kind==ConsumableKind::Regeneration?BuffKind::ItemRecovery:c.kind==ConsumableKind::Invulnerability?BuffKind::ItemInvulnerability:c.kind==ConsumableKind::Protection?BuffKind::ItemProtection:c.kind==ConsumableKind::SpellShield?BuffKind::SpellShield:BuffKind::ItemSpeed;b.persistent=c.kind==ConsumableKind::SpellShield && b.remaining<=0;b.physical=b.invulnerable=c.kind==ConsumableKind::Invulnerability;b.dispellable=!b.physical;b.breakOnDamage=c.breakOnDamage;b.healRate=c.kind==ConsumableKind::Regeneration?c.heal/float(b.remaining):0;b.manaRate=c.kind==ConsumableKind::Regeneration?c.mana/float(b.remaining):0;if(c.kind==ConsumableKind::Protection || c.kind==ConsumableKind::SpellShield){b.armor=s.armor;b.originAbility=s.ability;b.sourceLevel=s.level;b.sourceOwner=user->owner;}b.moveBonus=c.kind==ConsumableKind::Speed?s.moveBonus:0;b.moveLimit=c.kind==ConsumableKind::Speed?gameplayNumber(u->building?"MaxBldgSpeed":"MaxUnitSpeed",c.moveLimit):0;auto visual=s;visual.ability=s.buff;b.visuals=spellVisual(visual,"TargetArt",id,{u->x,u->y},false);u->buffs.emplace(s.buff,std::move(b));spellVisual(s,"TargetArt",id,{u->x,u->y});
    }
    if(c.kind==ConsumableKind::Dispel)spellVisual(s,"EffectArt",0,where);if(current()){spellEvent(source,cast,3);if(current())spellEvent(source,cast,4);}return true;
}
